#version 330
#extension GL_ARB_separate_shader_objects : require

#include <minecraft:globals.glsl>
#include <bus:bus.glsl>

// Decode the data bus, check that the values are consistent, redraw the sky from them.
uniform sampler2D InSampler;
uniform sampler2D DepthSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

int busTexelRow(int row, bool fromBottom, int height) {
    return fromBottom ? row : height - 1 - row;
}

vec4 busTexel(int row, bool fromBottom, ivec2 size) {
    return texelFetch(InSampler, ivec2(0, busTexelRow(row, fromBottom, size.y)), 0);
}

bool isMarker(vec4 c) {
    return all(lessThan(abs(c.rgb - vec3(1.0, 0.0, 1.0)), vec3(0.01)));
}

void main() {
    ivec2 size = textureSize(InSampler, 0);
    ivec2 pixel = ivec2(texCoord * vec2(size));
    vec3 color = texture(InSampler, texCoord).rgb;

    bool fromBottom = isMarker(texelFetch(InSampler, ivec2(0, 0), 0));
    bool present = fromBottom || isMarker(texelFetch(InSampler, ivec2(0, size.y - 1), 0));

    if (present) {
        mat4 proj;
        mat4 view;
        for (int i = 0; i < 16; i++) {
            proj[i / 4][i % 4] = bus_unpack_float(busTexel(BUS_ROW_PROJ + i, fromBottom, size));
            view[i / 4][i % 4] = bus_unpack_float(busTexel(BUS_ROW_VIEW + i, fromBottom, size));
        }
        vec3 skyColor = busTexel(BUS_ROW_SKY, fromBottom, size).rgb;
        vec3 fogColor = busTexel(BUS_ROW_FOG, fromBottom, size).rgb;
        vec3 sunDir = vec3(bus_unpack_signed(busTexel(BUS_ROW_SUN, fromBottom, size)),
                           bus_unpack_signed(busTexel(BUS_ROW_SUN + 1, fromBottom, size)),
                           bus_unpack_signed(busTexel(BUS_ROW_SUN + 2, fromBottom, size)));

        // Consistency checks.
        float fov = degrees(2.0 * atan(1.0 / proj[1][1]));
        bool fovOk = abs(fov - 70.0) < 0.5;
        bool aspectOk = abs(proj[0][0] * ScreenSize.x / ScreenSize.y - proj[1][1]) < 0.01;
        bool viewOk = abs(determinant(mat3(view)) - 1.0) < 0.01;
        bool sunOk = abs(length(sunDir) - 1.0) < 0.01;

        // Sky pixels (depth 0: nothing drawn, reversed depth) get a sky computed from the bus.
        float depth = texture(DepthSampler, texCoord).r;
        if (depth <= 0.0) {
            vec4 nearPoint = inverse(proj) * vec4(texCoord * 2.0 - 1.0, 1.0, 1.0);
            vec3 viewDir = normalize(nearPoint.xyz / nearPoint.w);
            vec3 worldDir = transpose(mat3(view)) * viewDir;     // the view matrix maps world to view
            color = mix(fogColor, skyColor, smoothstep(-0.02, 0.3, worldDir.y));
            float sun = smoothstep(0.9990, 0.9995, dot(viewDir, sunDir));
            color = mix(color, vec3(1.0, 0.95, 0.8), sun);
        }

        // Status squares, top-left, one per check (FOV, aspect, view, sun): green if it passes.
        bool checks[4] = bool[4](fovOk, aspectOk, viewOk, sunOk);
        for (int c = 0; c < 4; c++) {
            if (pixel.x >= 8 + c * 40 && pixel.x < 40 + c * 40 && pixel.y >= size.y - 40 && pixel.y < size.y - 8) {
                color = checks[c] ? vec3(0.1, 0.9, 0.2) : vec3(0.9, 0.1, 0.1);
            }
        }
        // Fifth square: where the bus starts in the texture. Blue: texel row 0. Yellow: the last row.
        if (pixel.x >= 168 && pixel.x < 200 && pixel.y >= size.y - 40 && pixel.y < size.y - 8) {
            color = fromBottom ? vec3(0.1, 0.3, 1.0) : vec3(1.0, 0.9, 0.1);
        }
    }

    // Paint the bus column over with its neighbour.
    if (pixel.x == 0) {
        color = texelFetch(InSampler, ivec2(1, pixel.y), 0).rgb;
    }
    fragColor = vec4(color, 1.0);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

uniform sampler2D InSampler;

layout(location = 0) in vec2 texCoord;
layout(location = 0) out vec4 fragColor;

void main() {
    fragColor = vec4(texture(InSampler, texCoord).rgb, 1.0);
}

#version 330
#extension GL_ARB_separate_shader_objects : require

// Full-screen triangle for post passes, shipped with the pack (vanilla renamed its own in 26.4).
layout(location = 0) out vec2 texCoord;

void main() {
    vec2 uv = vec2((gl_VertexIndex << 1) & 2, gl_VertexIndex & 2);
    gl_Position = vec4(uv * 2.0 - 1.0, 0.0, 1.0);
    texCoord = uv;
}

#ifndef BUS_BUS_GLSL
#define BUS_BUS_GLSL

// Data bus.
//
// Column x = 0 of the screen carries values from core shaders to the post effects. Every program that
// draws the world discards its fragments in that column (BUS_PROTECT), and the writers relocate
// their geometry onto a strip of it. The post effects read the values, then paint the column over.
//
// Rows, numbered from NDC y = -1 (the bottom of the screen):
#define BUS_ROW_MARKER 0      // magenta: the bus was written this frame
#define BUS_ROW_PROJ 1        // ProjMat, 16 floats, column-major
#define BUS_ROW_VIEW 17       // view rotation (the sky's ModelViewMat), 16 floats, column-major
#define BUS_ROW_SKY 33        // sky color (ColorModulator of the sky disc), 3 channels
#define BUS_ROW_FOG 34        // FogColor
#define BUS_SKY_ROWS 35       // rows written by the sky
#define BUS_ROW_SUN 35        // view-space sun direction: 3 components, 24-bit fixed point
#define BUS_SUN_ROWS 3
// The sun is drawn with additive blending (color = src * alpha + dst), after the sky: the sky clears the
// sun's rows to black first, so the sum is exactly what the sun writes.
#define BUS_SKY_STRIP_ROWS 38 // rows covered by the sky's strip: its own values, then the cleared sun rows

// Discard fragments that would land on the bus column. Orthographic renders (the GUI, and the GUI item
// atlas, which core/item draws into) are left alone: they happen elsewhere or after the post effects.
// Needs ProjMat (#include <minecraft:projection.glsl>).
#define BUS_PROTECT if (gl_FragCoord.x < 1.0 && ProjMat[2][3] != 0.0) { discard; }
// For full-screen copies onto the world (blit_screen), which have no ProjMat.
#define BUS_PROTECT_ALWAYS if (gl_FragCoord.x < 1.0) { discard; }

// A float as 4 bytes (RGBA). Only for writers without blending: the alpha channel is part of the value.
vec4 bus_pack_float(float v) {
    uint b = floatBitsToUint(v);
    return vec4(float((b >> 24u) & 255u), float((b >> 16u) & 255u), float((b >> 8u) & 255u), float(b & 255u)) / 255.0;
}

float bus_unpack_float(vec4 c) {
    uvec4 b = uvec4(round(c * 255.0));
    return uintBitsToFloat((b.x << 24u) | (b.y << 16u) | (b.z << 8u) | b.w);
}

// A value in [-1, 1] as 24-bit fixed point in RGB, alpha 1: safe for writers with alpha blending.
vec4 bus_pack_signed(float v) {
    uint q = uint(round(clamp(v * 0.5 + 0.5, 0.0, 1.0) * 16777215.0));
    return vec4(float((q >> 16u) & 255u), float((q >> 8u) & 255u), float(q & 255u), 255.0) / 255.0;
}

float bus_unpack_signed(vec4 c) {
    uvec3 b = uvec3(round(c.rgb * 255.0));
    return float((b.x << 16u) | (b.y << 8u) | b.z) / 16777215.0 * 2.0 - 1.0;
}

// Clip-space position of a corner of the strip covering bus rows [firstRow, firstRow + rows).
// corner is (0 or 1, 0 or 1). Corners (0,0), (1,0), (1,1), (0,1) in that order are front-facing.
vec4 bus_strip_corner(vec2 corner, int firstRow, int rows, vec2 screenSize) {
    vec2 pixel = vec2(corner.x, float(firstRow) + corner.y * float(rows));
    return vec4(-1.0 + 2.0 * pixel / screenSize, 0.0, 1.0);
}

#endif

