layout(location = 1) out float cylindricalVertexDistance;
// The bus row each fragment writes.
layout(location = 2) out float busRow;

cylindricalVertexDistance = fog_cylindrical_distance(Position);

// The sky disc becomes the data bus writer. Its 10 vertices are a triangle fan around vertex 0:
// vertices 0, 1, 2, 3 make the strip's two triangles, the others collapse onto vertex 3.
// The visible sky is redrawn by the post effect from the values written here.
int i = gl_VertexIndex;
vec2 corner = i == 0 ? vec2(0.0, 0.0) : i == 1 ? vec2(1.0, 0.0) : i == 2 ? vec2(1.0, 1.0) : vec2(0.0, 1.0);
gl_Position = bus_strip_corner(corner, 0, BUS_SKY_STRIP_ROWS, ScreenSize);
busRow = corner.y * float(BUS_SKY_STRIP_ROWS);

// Write the data bus (see bus:bus.glsl). The sky pipeline has no blending: all 4 channels are kept.
int row = int(floor(busRow));
if (row == BUS_ROW_MARKER) {
    fragColor = vec4(1.0, 0.0, 1.0, 1.0);
} else if (row < BUS_ROW_VIEW) {
    int k = row - BUS_ROW_PROJ;
    fragColor = bus_pack_float(ProjMat[k / 4][k % 4]);
} else if (row < BUS_ROW_SKY) {
    int k = row - BUS_ROW_VIEW;
    fragColor = bus_pack_float(ModelViewMat[k / 4][k % 4]);
} else if (row == BUS_ROW_SKY) {
    fragColor = vec4(ColorModulator.rgb, 1.0);
} else if (row == BUS_ROW_FOG) {
    fragColor = vec4(FogColor.rgb, 1.0);
} else {
    fragColor = vec4(0.0, 0.0, 0.0, 1.0);   // the sun's rows, cleared for its additive blending
}

layout(location = 0) out vec2 texCoord0;
// The sun writes its direction onto the data bus.
layout(location = 1) flat out int isSun;
layout(location = 2) out float busRow;
layout(location = 3) flat out vec3 sunDirection;

texCoord0 = UV0;

// The sun and the moon both use this program. The sun quad is scaled by 30, the moon's by 20.
isSun = abs(length(ModelViewMat[0].xyz) - 30.0) < 1.0 ? 1 : 0;
busRow = 0.0;
// Direction of the sun's center, in view space: the quad is centered on its local origin.
sunDirection = normalize((ModelViewMat * vec4(0.0, 0.0, 0.0, 1.0)).xyz);
if (isSun == 1) {
    int k = gl_VertexIndex % 4;
    vec2 corner = vec2(k == 1 || k == 2 ? 1.0 : 0.0, k == 2 || k == 3 ? 1.0 : 0.0);
    gl_Position = bus_strip_corner(corner, BUS_ROW_SUN, BUS_SUN_ROWS, ScreenSize);
    busRow = float(BUS_ROW_SUN) + corner.y * float(BUS_SUN_ROWS);
}

layout(location = 0) in vec2 texCoord0;
layout(location = 1) flat in int isSun;
layout(location = 2) in float busRow;
layout(location = 3) flat in vec3 sunDirection;

void main() {
    // The sun writes its view-space direction (celestial blends with alpha: RGB fixed point, alpha 1).
    if (isSun == 1) {
        int k = int(floor(busRow)) - BUS_ROW_SUN;
        fragColor = bus_pack_signed(k == 0 ? sunDirection.x : k == 1 ? sunDirection.y : sunDirection.z);
        return;
    }
    BUS_PROTECT
